def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    tree = [0] * (len(ranks) + 1)
    size = len(ranks)
    result = []

    for i, value in enumerate(a):
        rank = ranks[value]
        pos = rank
        not_taller = 0
        while pos:
            not_taller += tree[pos]
            pos -= pos & -pos

        result.append(min(i, k) - not_taller)

        pos = rank
        while pos <= size:
            tree[pos] += 1
            pos += pos & -pos

        if i >= k:
            pos = ranks[a[i - k]]
            while pos <= size:
                tree[pos] -= 1
                pos += pos & -pos

    return result
